namespace CourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Code { get; set; } = "";
    public string Name { get; set; } = "";
    public string Description { get; set; } = "";
}

public class Instructor
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string Title { get; set; } = "";
    public string Bio { get; set; } = "";
    public string Email { get; set; } = "";
}

public class Course
{
    public int Id { get; set; }
    public string CourseCode { get; set; } = "";
    public string Title { get; set; } = "";
    public string Description { get; set; } = "";
    public int Credits { get; set; }
    public string Schedule { get; set; } = "";
    public string Room { get; set; } = "";
    public int DepartmentId { get; set; }
    public Department Department { get; set; } = null!;
    public Instructor Instructor { get; set; } = null!;
    public bool IsFeatured { get; set; }
    public int MaxEnrollment { get; set; }
    public int CurrentEnrollment { get; set; }
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = "";
    public string StudentId { get; set; } = "";
    public int CourseId { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Pure and applied mathematics, statistics, and data analysis." },
            new() { Id = 3, Code = "ENG", Name = "English", Description = "Literature, writing, and communication studies." },
            new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Exploration of human civilizations, events, and cultural development." },
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Sarah Chen", Title = "Professor of Computer Science", Bio = "Dr. Chen specializes in distributed systems and cloud computing. She has published over 40 papers and previously worked at a major tech company.", Email = "s.chen@university.edu" },
            new() { Id = 2, Name = "Dr. James Wilson", Title = "Associate Professor of Mathematics", Bio = "Dr. Wilson's research focuses on number theory and cryptography. He received his PhD from MIT and has been teaching for 15 years.", Email = "j.wilson@university.edu" },
            new() { Id = 3, Name = "Prof. Maria Garcia", Title = "Professor of English", Bio = "Prof. Garcia is a published author and literary critic specializing in contemporary American fiction and creative writing.", Email = "m.garcia@university.edu" },
            new() { Id = 4, Name = "Dr. Robert Kim", Title = "Associate Professor of Physics", Bio = "Dr. Kim conducts research in quantum mechanics and particle physics. He leads the university's particle accelerator lab.", Email = "r.kim@university.edu" },
            new() { Id = 5, Name = "Dr. Emily Thompson", Title = "Professor of History", Bio = "Dr. Thompson is an expert in medieval European history and has authored three books on the subject.", Email = "e.thompson@university.edu" },
            new() { Id = 6, Name = "Dr. Alan Patel", Title = "Assistant Professor of Computer Science", Bio = "Dr. Patel researches machine learning and artificial intelligence, with a focus on natural language processing.", Email = "a.patel@university.edu" },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, CourseCode = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Room = "Science Hall 201", DepartmentId = 1, Department = _departments[0], Instructor = _instructors[0], IsFeatured = true, MaxEnrollment = 120, CurrentEnrollment = 98 },
            new() { Id = 2, CourseCode = "CS 301", Title = "Data Structures & Algorithms", Description = "In-depth study of data structures (trees, graphs, hash tables) and algorithm design techniques (divide-and-conquer, dynamic programming, greedy algorithms).", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", Room = "Science Hall 305", DepartmentId = 1, Department = _departments[0], Instructor = _instructors[0], IsFeatured = true, MaxEnrollment = 60, CurrentEnrollment = 55 },
            new() { Id = 3, CourseCode = "CS 420", Title = "Machine Learning", Description = "Introduction to machine learning concepts including supervised and unsupervised learning, neural networks, and model evaluation techniques.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", Room = "Tech Building 110", DepartmentId = 1, Department = _departments[0], Instructor = _instructors[5], IsFeatured = true, MaxEnrollment = 45, CurrentEnrollment = 44 },
            new() { Id = 4, CourseCode = "MATH 201", Title = "Calculus II", Description = "Continuation of single-variable calculus: techniques of integration, sequences, series, and introduction to multivariable calculus.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Room = "Math Building 102", DepartmentId = 2, Department = _departments[1], Instructor = _instructors[1], IsFeatured = false, MaxEnrollment = 80, CurrentEnrollment = 65 },
            new() { Id = 5, CourseCode = "MATH 310", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications to data science and engineering.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", Room = "Math Building 205", DepartmentId = 2, Department = _departments[1], Instructor = _instructors[1], IsFeatured = true, MaxEnrollment = 50, CurrentEnrollment = 42 },
            new() { Id = 6, CourseCode = "ENG 102", Title = "Composition & Rhetoric", Description = "Develop academic writing skills through essay composition, argumentation, research methods, and critical analysis of texts.", Credits = 3, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Room = "Humanities 301", DepartmentId = 3, Department = _departments[2], Instructor = _instructors[2], IsFeatured = false, MaxEnrollment = 30, CurrentEnrollment = 28 },
            new() { Id = 7, CourseCode = "ENG 250", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present, examining themes of identity, freedom, and social change.", Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", Room = "Humanities 210", DepartmentId = 3, Department = _departments[2], Instructor = _instructors[2], IsFeatured = false, MaxEnrollment = 35, CurrentEnrollment = 20 },
            new() { Id = 8, CourseCode = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions. Calculus-based approach to fundamental physics principles.", Credits = 4, Schedule = "Mon/Wed 9:00–10:20 AM + Fri Lab", Room = "Physics Lab 100", DepartmentId = 4, Department = _departments[3], Instructor = _instructors[3], IsFeatured = false, MaxEnrollment = 90, CurrentEnrollment = 72 },
            new() { Id = 9, CourseCode = "PHYS 340", Title = "Quantum Mechanics", Description = "Introduction to quantum theory: wave functions, Schrödinger equation, quantum states, measurement, and applications to atomic physics.", Credits = 3, Schedule = "Tue/Thu 10:00–11:20 AM", Room = "Physics Lab 220", DepartmentId = 4, Department = _departments[3], Instructor = _instructors[3], IsFeatured = true, MaxEnrollment = 30, CurrentEnrollment = 25 },
            new() { Id = 10, CourseCode = "HIST 101", Title = "World Civilizations", Description = "Survey of major world civilizations from antiquity to 1500 CE, examining political, social, and cultural developments.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Room = "Liberal Arts 105", DepartmentId = 5, Department = _departments[4], Instructor = _instructors[4], IsFeatured = false, MaxEnrollment = 100, CurrentEnrollment = 78 },
            new() { Id = 11, CourseCode = "HIST 320", Title = "Medieval Europe", Description = "In-depth study of European history from the fall of Rome to the Renaissance, covering feudalism, the Church, and the Crusades.", Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM", Room = "Liberal Arts 210", DepartmentId = 5, Department = _departments[4], Instructor = _instructors[4], IsFeatured = false, MaxEnrollment = 40, CurrentEnrollment = 32 },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        var course = GetCourse(request.CourseId);
        if (course == null) return false;
        // In a real app, this would persist to a database
        return true;
    }
}

