@page "/"

@using CourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>University Course Catalog</PageTitle>

<div class="hero">
    <h1>University Course Catalog</h1>
    <p>Browse courses, explore departments, and enroll for the upcoming semester.</p>
    <a href="/courses" class="btn btn-primary">Browse All Courses</a>
    <a href="/enroll" class="btn btn-secondary">Enroll Now</a>
</div>

<section class="featured-section">
    <h2>Featured Courses</h2>
    <div class="course-grid">
        @foreach (var course in featuredCourses)
        {
            <div class="course-card">
                <span class="badge">@course.Department.Code</span>
                <h3><a href="/courses/@course.Id">@course.Title</a></h3>
                <p class="course-code">@course.CourseCode · @course.Credits credits</p>
                <p>@course.Instructor.Name</p>
                <p class="schedule">@course.Schedule</p>
            </div>
        }
    </div>
</section>

<section class="departments-section">
    <h2>Departments</h2>
    <div class="dept-grid">
        @foreach (var dept in departments)
        {
            <a href="/courses?departmentId=@dept.Id" class="dept-card">
                <h3>@dept.Name</h3>
                <p>@dept.Description</p>
            </a>
        }
    </div>
</section>

@code {
    private List<CourseCatalog.Models.Course> featuredCourses = new();
    private List<CourseCatalog.Models.Department> departments = new();

    protected override void OnInitialized()
    {
        featuredCourses = Catalog.GetFeaturedCourses();
        departments = Catalog.GetDepartments();
    }
}

@page "/courses"

@using CourseCatalog.Models
@using CourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Courses - University Course Catalog</PageTitle>

<h1>Course Catalog</h1>

<form method="get" class="filter-form">
    <input type="text" name="search" value="@Search" placeholder="Search courses, instructors..." class="search-input" />
    <select name="departmentId" class="dept-select">
        <option value="">All Departments</option>
        @foreach (var dept in departments)
        {
            <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
        }
    </select>
    <button type="submit" class="btn btn-primary">Search</button>
    @if (!string.IsNullOrEmpty(Search) || DepartmentId.HasValue)
    {
        <a href="/courses" class="btn btn-secondary">Clear</a>
    }
</form>

@if (courses.Count == 0)
{
    <p class="no-results">No courses found matching your criteria.</p>
}
else
{
    <p class="results-count">Showing @courses.Count course(s)</p>
    <div class="course-list">
        @foreach (var course in courses)
        {
            <div class="course-list-item">
                <div class="course-list-header">
                    <h3><a href="/courses/@course.Id">@course.Title</a></h3>
                    <span class="badge">@course.CourseCode</span>
                </div>
                <p class="course-meta">
                    @course.Department.Name · @course.Credits credits · @course.Instructor.Name
                </p>
                <p>@course.Description</p>
                <p class="schedule">@course.Schedule · @course.Room</p>
                <p class="enrollment-status">
                    Enrollment: @course.CurrentEnrollment / @course.MaxEnrollment
                    @if (course.CurrentEnrollment >= course.MaxEnrollment)
                    {
                        <span class="full-badge">FULL</span>
                    }
                </p>
            </div>
        }
    </div>
}

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public int? DepartmentId { get; set; }

    private List<Course> courses = new();
    private List<Department> departments = new();

    protected override void OnInitialized()
    {
        departments = Catalog.GetDepartments();
        courses = Catalog.GetCourses(Search, DepartmentId);
    }
}

@page "/courses/{Id:int}"

@using CourseCatalog.Models
@using CourseCatalog.Services
@inject CatalogService Catalog

@if (course == null)
{
    <PageTitle>Course Not Found</PageTitle>
    <h1>Course Not Found</h1>
    <p>The requested course does not exist.</p>
    <a href="/courses">← Back to catalog</a>
}
else
{
    <PageTitle>@course.Title - University Course Catalog</PageTitle>

    <nav class="breadcrumb">
        <a href="/">Home</a> &gt;
        <a href="/courses">Courses</a> &gt;
        <a href="/courses?departmentId=@course.DepartmentId">@course.Department.Name</a> &gt;
        <span>@course.CourseCode</span>
    </nav>

    <article class="course-detail">
        <header>
            <h1>@course.Title</h1>
            <span class="badge large">@course.CourseCode</span>
        </header>

        <section class="detail-grid">
            <div class="detail-main">
                <h2>Description</h2>
                <p>@course.Description</p>

                <h2>Schedule &amp; Location</h2>
                <dl>
                    <dt>Schedule</dt>
                    <dd>@course.Schedule</dd>
                    <dt>Room</dt>
                    <dd>@course.Room</dd>
                    <dt>Credits</dt>
                    <dd>@course.Credits</dd>
                </dl>

                <h2>Enrollment</h2>
                <p>
                    @course.CurrentEnrollment / @course.MaxEnrollment seats filled
                    @if (course.CurrentEnrollment >= course.MaxEnrollment)
                    {
                        <span class="full-badge">FULL</span>
                    }
                    else
                    {
                        <span class="open-badge">@(course.MaxEnrollment - course.CurrentEnrollment) seats available</span>
                    }
                </p>
                @if (course.CurrentEnrollment < course.MaxEnrollment)
                {
                    <a href="/enroll?courseId=@course.Id" class="btn btn-primary">Enroll in This Course</a>
                }
            </div>

            <aside class="detail-sidebar">
                <div class="instructor-card">
                    <h2>Instructor</h2>
                    <h3>@course.Instructor.Name</h3>
                    <p class="instructor-title">@course.Instructor.Title</p>
                    <p>@course.Instructor.Bio</p>
                    <p class="instructor-email">✉ @course.Instructor.Email</p>
                </div>
            </aside>
        </section>
    </article>
}

@code {
    [Parameter] public int Id { get; set; }

    private Course? course;

    protected override void OnInitialized()
    {
        course = Catalog.GetCourse(Id);
    }
}

@page "/enroll"

@using CourseCatalog.Models
@using CourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Enrollment Request - University Course Catalog</PageTitle>

<h1>Enrollment Request</h1>

@if (submitted)
{
    <div class="success-message">
        <h2>Request Submitted Successfully</h2>
        <p>Your enrollment request for <strong>@selectedCourseTitle</strong> has been received. You will receive a confirmation at your university email.</p>
        <a href="/courses" class="btn btn-primary">Back to Courses</a>
        <a href="/enroll" class="btn btn-secondary">Submit Another Request</a>
    </div>
}
else
{
    <p>Complete this form to submit an enrollment request. All fields are required.</p>

    @if (errors.Count > 0)
    {
        <div class="error-summary">
            <ul>
                @foreach (var error in errors)
                {
                    <li>@error</li>
                }
            </ul>
        </div>
    }

    <form method="post" class="enroll-form">
        <AntiforgeryToken />

        <div class="form-group">
            <label for="studentName">Full Name</label>
            <input type="text" id="studentName" name="Model.StudentName" value="@Model.StudentName" required />
        </div>

        <div class="form-group">
            <label for="studentId">Student ID</label>
            <input type="text" id="studentId" name="Model.StudentId" value="@Model.StudentId" placeholder="e.g., STU-12345" required />
        </div>

        <div class="form-group">
            <label for="courseId">Course</label>
            <select id="courseId" name="Model.CourseId" required>
                <option value="0">-- Select a course --</option>
                @foreach (var course in courses)
                {
                    <option value="@course.Id" selected="@(Model.CourseId == course.Id)">
                        @course.CourseCode - @course.Title (@course.Credits cr)
                    </option>
                }
            </select>
        </div>

        <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
    </form>
}

@code {
    [SupplyParameterFromForm] public EnrollmentRequest Model { get; set; } = new();
    [SupplyParameterFromQuery] public int? CourseId { get; set; }

    private List<Course> courses = new();
    private List<string> errors = new();
    private bool submitted;
    private string selectedCourseTitle = "";

    protected override void OnInitialized()
    {
        courses = Catalog.GetCourses();

        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    protected override void OnParametersSet()
    {
        // Handle form POST
        if (HttpMethods.IsPost(HttpContextAccessor?.HttpContext?.Request.Method ?? ""))
        {
            Validate();
            if (errors.Count == 0)
            {
                var success = Catalog.SubmitEnrollmentRequest(Model);
                if (success)
                {
                    var course = Catalog.GetCourse(Model.CourseId);
                    selectedCourseTitle = course?.Title ?? "Unknown Course";
                    submitted = true;
                }
                else
                {
                    errors.Add("The selected course was not found.");
                }
            }
        }
    }

    private void Validate()
    {
        errors.Clear();
        if (string.IsNullOrWhiteSpace(Model.StudentName))
            errors.Add("Full Name is required.");
        if (string.IsNullOrWhiteSpace(Model.StudentId))
            errors.Add("Student ID is required.");
        if (Model.CourseId == 0)
            errors.Add("Please select a course.");
    }

    [CascadingParameter] public HttpContext? HttpContextAccessor { get; set; }
}

