arguments.new_str:
@page "/enroll"

@using CourseCatalog.Models
@using CourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Enrollment Request - University Course Catalog</PageTitle>

<h1>Enrollment Request</h1>

@if (submitted)
{
    <div class="success-message">
        <h2>Request Submitted Successfully</h2>
        <p>Your enrollment request for <strong>@selectedCourseTitle</strong> has been received. You will receive a confirmation at your university email.</p>
        <a href="/courses" class="btn btn-primary">Back to Courses</a>
        <a href="/enroll" class="btn btn-secondary">Submit Another Request</a>
    </div>
}
else
{
    <p>Complete this form to submit an enrollment request. All fields are required.</p>

    @if (errors.Count > 0)
    {
        <div class="error-summary">
            <ul>
                @foreach (var error in errors)
                {
                    <li>@error</li>
                }
            </ul>
        </div>
    }

    <form method="post" @formname="enrollment" class="enroll-form">
        <AntiforgeryToken />

        <div class="form-group">
            <label for="studentName">Full Name</label>
            <input type="text" id="studentName" name="Model.StudentName" value="@Model.StudentName" required />
        </div>

        <div class="form-group">
            <label for="studentId">Student ID</label>
            <input type="text" id="studentId" name="Model.StudentId" value="@Model.StudentId" placeholder="e.g., STU-12345" required />
        </div>

        <div class="form-group">
            <label for="courseId">Course</label>
            <select id="courseId" name="Model.CourseId" required>
                <option value="0">-- Select a course --</option>
                @foreach (var course in courses)
                {
                    <option value="@course.Id" selected="@(Model.CourseId == course.Id)">
                        @course.CourseCode - @course.Title (@course.Credits cr)
                    </option>
                }
            </select>
        </div>

        <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
    </form>
}

@code {
    [SupplyParameterFromForm] public EnrollmentRequest? Model { get; set; }
    [SupplyParameterFromQuery] public int? CourseId { get; set; }

    private List<Course> courses = new();
    private List<string> errors = new();
    private bool submitted;
    private string selectedCourseTitle = "";

    protected override void OnInitialized()
    {
        Model ??= new EnrollmentRequest();
        courses = Catalog.GetCourses();

        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }

        // If model was populated from form POST, process submission
        if (!string.IsNullOrWhiteSpace(Model.StudentName) || !string.IsNullOrWhiteSpace(Model.StudentId) || Model.CourseId != 0)
        {
            if (HasFormData())
            {
                Validate();
                if (errors.Count == 0)
                {
                    var success = Catalog.SubmitEnrollmentRequest(Model);
                    if (success)
                    {
                        var course = Catalog.GetCourse(Model.CourseId);
                        selectedCourseTitle = course?.Title ?? "Unknown Course";
                        submitted = true;
                    }
                    else
                    {
                        errors.Add("The selected course was not found.");
                    }
                }
            }
        }
    }

    private bool HasFormData()
    {
        // SupplyParameterFromForm only populates on POST
        return !string.IsNullOrWhiteSpace(Model!.StudentName) ||
               !string.IsNullOrWhiteSpace(Model.StudentId) ||
               Model.CourseId > 0;
    }

    private void Validate()
    {
        errors.Clear();
        if (string.IsNullOrWhiteSpace(Model!.StudentName))
            errors.Add("Full Name is required.");
        if (string.IsNullOrWhiteSpace(Model.StudentId))
            errors.Add("Student ID is required.");
        if (Model.CourseId == 0)
            errors.Add("Please select a course.");
    }
}

